import React, { useState } from 'react';
import axios from 'axios';

const ContentForm = () => {
  const [title, setTitle] = useState('');
  const [content, setContent] = useState('');

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      const response = await axios.post('/api/content', { title, content });
      // Manejar la respuesta del servidor
    } catch (error) {
      console.error('Error al crear contenido:', error);
    }
  };

  return (
    <form onSubmit={handleSubmit}>
      <input type="text" value={title} onChange={(e) => setTitle(e.target.value)} placeholder="Título" />
      <textarea value={content} onChange={(e) => setContent(e.target.value)} placeholder="Contenido"></textarea>
      <button type="submit">Crear Contenido</button>
    </form>
  );
};

export default ContentForm;
